<template><view class="chat-page"><view class="toolbar"><picker :range="sessions" range-key="title" @change="choose(Number($event.detail.value))"><view class="session">{{active?.title || '选择会话'}} ⌄</view></picker><button size="mini" :disabled="busy" @click="create">新对话</button><button v-if="active" size="mini" :disabled="busy" @click="rename">改名</button><button v-if="active" size="mini" :disabled="busy" @click="remove">删除</button></view><view v-if="error" class="error">{{error}}<text @click="load">重试</text></view><scroll-view scroll-y class="messages" :scroll-into-view="lastId"><view v-for="(m,index) in messages" :key="m.messageId || index" :id="'message-'+index" :class="['bubble',m.role==='user'?'mine':'reply']"><text class="role">{{m.role==='user'?'我':'农事智能助手'}}</text><text selectable class="content">{{m.content}}</text><text v-if="m.createdAt" class="time">{{m.createdAt}}</text></view><view v-if="!messages.length" class="empty">创建或选择会话，描述作物、地块和遇到的问题。</view><view v-if="busy" class="empty">正在处理，请稍候…</view></scroll-view><view class="composer"><textarea v-model="input" auto-height :maxlength="4000" placeholder="描述你的农事问题" :disabled="busy"/><button :loading="busy" :disabled="busy||!input.trim()||!active" @click="send">发送</button></view></view></template>
<script setup lang="ts">
import {ref,nextTick} from 'vue'
import {onShow,onHide} from '@dcloudio/uni-app'
import {call} from '@/api/native-business'
import type {Row} from '@/api/native-business'
import {ensureWorkspaceSession,isProductionOps} from '@/utils/workspace'
import {productionContextVersion} from '@/utils/request'
const sessions=ref<Row[]>([]),active=ref<Row>(),messages=ref<Row[]>([]),input=ref(''),busy=ref(false),error=ref(''),lastId=ref('')
let version=0,scope=0
async function load(){error.value='';try{if(!await ensureWorkspaceSession())return;if(isProductionOps())throw new Error('请切换到用户端');scope=productionContextVersion();sessions.value=await call('/ai/assistant/sessions');if(active.value){const index=sessions.value.findIndex(s=>s.sessionId===active.value?.sessionId);if(index>=0)await choose(index);else{active.value=undefined;messages.value=[]}}}catch(e:any){error.value=e.message}}
async function choose(index:number){if(busy.value)return;const token=++version;active.value=sessions.value[index];if(!active.value)return;error.value='';messages.value=[];try{const list=await call('/ai/assistant/sessions/'+active.value.sessionId+'/messages');if(token===version){messages.value=list;await scroll()}}catch(e:any){error.value=e.message}}
async function scroll(){await nextTick();lastId.value='message-'+(messages.value.length-1)}
async function create(){if(busy.value)return;busy.value=true;error.value='';try{active.value=await call('/ai/assistant/sessions','POST',{title:'新对话'});sessions.value=[active.value!,...sessions.value];messages.value=[]}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function send(){if(busy.value||!input.value.trim()||!active.value)return;const content=input.value.trim(),sessionId=active.value.sessionId;busy.value=true;error.value='';try{if(scope!==productionContextVersion())throw new Error('业务范围已变更，请重新进入');const result=await call('/ai/assistant/messages','POST',{sessionId,content});if(!result?.content)throw new Error('服务未返回回答，请稍后重试');input.value='';messages.value=await call('/ai/assistant/sessions/'+sessionId+'/messages');await scroll()}catch(e:any){error.value=e.message}finally{busy.value=false}}
function rename(){if(!active.value||busy.value)return;uni.showModal({title:'修改会话名称',editable:true,placeholderText:'请输入名称',success:async r=>{if(!r.confirm||!r.content?.trim())return;busy.value=true;try{await call('/ai/assistant/sessions/'+active.value!.sessionId,'PUT',{title:r.content.trim()});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}})}
function remove(){if(!active.value||busy.value)return;uni.showModal({title:'删除会话',content:'删除后将无法继续查看该会话记录。',success:async r=>{if(!r.confirm)return;busy.value=true;try{await call('/ai/assistant/sessions/'+active.value!.sessionId,'DELETE');active.value=undefined;messages.value=[];await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}})}
onShow(()=>void load());onHide(()=>{version++;messages.value=[];active.value=undefined})
</script>
<style scoped>.chat-page{height:calc(100vh - var(--window-top,0px));display:flex;flex-direction:column;background:#f3f6f1}.toolbar{display:flex;flex-wrap:wrap;gap:14rpx;padding:20rpx 24rpx;background:white}.toolbar picker{flex:1;min-width:220rpx}.session{padding:16rpx;font-size:27rpx;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.toolbar button{margin:0;font-size:24rpx}.messages{flex:1;height:0;padding:24rpx;box-sizing:border-box}.bubble{padding:24rpx;margin-bottom:24rpx;border-radius:18rpx;max-width:90%;box-sizing:border-box}.mine{background:#dfeedd;margin-left:auto}.reply{background:white;margin-right:auto}.role,.time{display:block;color:#728170;font-size:24rpx;margin-bottom:14rpx}.content{display:block;white-space:pre-wrap;word-break:break-word;line-height:1.75;font-size:29rpx}.time{margin-top:18rpx;margin-bottom:0}.composer{display:flex;gap:18rpx;align-items:flex-end;padding:20rpx 24rpx calc(20rpx + env(safe-area-inset-bottom));background:white;border-top:1rpx solid #e1e8dc}.composer textarea{flex:1;min-height:80rpx;max-height:240rpx;background:#f3f6f0;border-radius:14rpx;padding:18rpx;box-sizing:border-box;font-size:28rpx}.composer button{margin:0;background:#0f7a45;color:#fff;font-size:26rpx}.error{padding:20rpx;background:#fff0e7;color:#a33;font-size:25rpx}.error text{margin-left:20rpx;text-decoration:underline}.empty{padding:44rpx 22rpx;text-align:center;color:#666666;line-height:1.6;font-size:27rpx}</style>
